// buildHTTPClient sets the standard idle and handshake timeouts, so idle sockets
// expire and a stalled TLS handshake cannot hang forever, while the proxy stays
// opt-in.
func TestBhvLanggo035_DefaultApiClientUnit_BuildHTTPClient_TransportHasStandardTimeoutsAndNoImplicitProxy(t *testing.T) {
	t.Parallel()
	opts, err := NewTransportOptionsBuilder().Build()
	if err != nil {
		t.Fatal(err)
	}
	guard, ok := buildHTTPClient(opts).Transport.(*locationGuardTransport)
	if !ok {
		t.Fatal("expected the Location guard around the *http.Transport")
	}
	transport, ok := guard.inner.(*http.Transport)
	if !ok {
		t.Fatal("expected the guard to wrap an *http.Transport")
	}
	if transport.IdleConnTimeout != 90*time.Second {
		t.Errorf("expected IdleConnTimeout 90s, got %v", transport.IdleConnTimeout)
	}
	if transport.TLSHandshakeTimeout != 10*time.Second {
		t.Errorf("expected TLSHandshakeTimeout 10s, got %v", transport.TLSHandshakeTimeout)
	}
	if transport.DialContext == nil {
		t.Error("expected a dialer with a timeout and keep-alive")
	}
	if transport.MaxIdleConnsPerHost != 10 {
		t.Errorf("expected 10 idle connections kept per host, got %d", transport.MaxIdleConnsPerHost)
	}
	if transport.Proxy != nil {
		t.Error("expected no implicit environment proxy")
	}
}

// A proxy named in the environment is not used: the SDK reads a proxy only from
// TransportOptions, so HTTP_PROXY and its siblings leave the transport proxy-free.
func TestBhvTransport009_DefaultApiClientUnit_IgnoresAmbientProxyEnvironmentWithoutProxy(t *testing.T) {
	t.Setenv("HTTP_PROXY", "http://127.0.0.1:1")
	t.Setenv("HTTPS_PROXY", "http://127.0.0.1:1")
	t.Setenv("http_proxy", "http://127.0.0.1:1")
	t.Setenv("https_proxy", "http://127.0.0.1:1")
	opts, err := NewTransportOptionsBuilder().Build()
	if err != nil {
		t.Fatal(err)
	}
	guard, ok := buildHTTPClient(opts).Transport.(*locationGuardTransport)
	if !ok {
		t.Fatal("expected the Location guard around the *http.Transport")
	}
	transport, ok := guard.inner.(*http.Transport)
	if !ok {
		t.Fatal("expected the guard to wrap an *http.Transport")
	}
	if transport.Proxy != nil {
		t.Error("expected no proxy from the ambient environment")
	}
}

// ── Redirect credential handling ──

// A redirect to another origin drops every credential header the caller sent,
// whichever one it is, while an ordinary header and the request itself still go
// through. The origins are two local servers, so this is a real net/http
// redirect through the client. net/http never strips Proxy-Authorization on a
// redirect, so that row can only pass through the client's own filter.
func TestBhvRedirects025_DefaultApiClientUnit_CrossOriginRedirectDropsEveryCredentialHeader(t *testing.T) {
	t.Parallel()
	for _, name := range []string{"Authorization", "Cookie", "Proxy-Authorization"} {
		t.Run(name, func(t *testing.T) {
			t.Parallel()
			var received http.Header
			target := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				received = r.Header.Clone()
				w.WriteHeader(200)
			}))
			defer target.Close()

			origin := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				w.Header().Set("Location", target.URL+"/followed")
				w.WriteHeader(302)
			}))
			defer origin.Close()

			transport, buildErr := NewTransportOptionsBuilder().
				FollowRedirects(true).
				Build()
			if buildErr != nil {
				t.Fatal(buildErr)
			}
			client := NewDefaultApiClient(transport)
			_, err := client.SendRequest("GET", origin.URL+"/start",
				map[string]string{name: "secret-value", "X-Plain": "kept"}, nil)
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if got := received.Get(name); got != "" {
				t.Errorf("expected %s to be dropped across origins, got %q", name, got)
			}
			if got := received.Get("X-Plain"); got != "kept" {
				t.Errorf("expected X-Plain to survive the redirect, got %q", got)
			}
		})
	}
}

// A 307 that stays on the same origin keeps Authorization and Cookie on the
// followed request, which replays the body under the same credentials.
func TestBhvRedirects013_DefaultApiClientUnit_SameOriginRedirectKeepsAuthorizationAndCookie(t *testing.T) {
	t.Parallel()
	var received http.Header
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/start" {
			w.Header().Set("Location", "/followed")
			w.WriteHeader(http.StatusTemporaryRedirect)
			return
		}
		received = r.Header.Clone()
		w.WriteHeader(http.StatusOK)
	}))
	defer server.Close()

	transport, buildErr := NewTransportOptionsBuilder().
		FollowRedirects(true).
		Build()
	if buildErr != nil {
		t.Fatal(buildErr)
	}
	client := NewDefaultApiClient(transport)
	_, err := client.SendRequest("POST", server.URL+"/start",
		map[string]string{
			"Authorization": "Bearer kept-token",
			"Cookie":        "session=kept",
			"Content-Type":  "application/x-www-form-urlencoded",
		},
		[]byte("grant_type=client_credentials"),
	)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got := received.Get("Authorization"); got != "Bearer kept-token" {
		t.Errorf("expected Authorization kept on a same-origin 307, got %q", got)
	}
	if got := received.Get("Cookie"); got != "session=kept" {
		t.Errorf("expected Cookie kept on a same-origin 307, got %q", got)
	}
}

// A redirect that stays on the same origin keeps the credentials: dropping them
// would turn a valid redirect into an unauthenticated request.
func TestBhvRedirects024_DefaultApiClientUnit_SameOriginRedirectKeepsCredentialHeaders(t *testing.T) {
	t.Parallel()
	var received http.Header
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/start" {
			w.Header().Set("Location", "/followed")
			w.WriteHeader(302)
			return
		}
		received = r.Header.Clone()
		w.WriteHeader(200)
	}))
	defer server.Close()

	transport, buildErr := NewTransportOptionsBuilder().
		FollowRedirects(true).
		Build()
	if buildErr != nil {
		t.Fatal(buildErr)
	}
	client := NewDefaultApiClient(transport)
	sent := map[string]string{
		"Authorization":       "Bearer kept-token",
		"Cookie":              "session=kept",
		"Proxy-Authorization": "Basic a2VwdA==",
	}
	if _, err := client.SendRequest("GET", server.URL+"/start", sent, nil); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	for name, want := range sent {
		if got := received.Get(name); got != want {
			t.Errorf("expected %s %q to be kept on a same-origin redirect, got %q", name, want, got)
		}
	}
}

// An explicit default port and an omitted one name the same origin, so a
// redirect from https://host to https://host:443 must not be treated as
// cross-origin and strip the credentials; a different scheme, host or
// non-default port still is.
func TestBhvRedirects030_DefaultApiClientUnit_SameOrigin_TreatsAnExplicitDefaultPortAsTheSameOrigin(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name string
		a, b string
		want bool
	}{
		{"https implicit versus explicit 443", "https://h.example.com/a", "https://h.example.com:443/b", true},
		{"http implicit versus explicit 80", "http://h.example.com/a", "http://h.example.com:80/b", true},
		{"host case is ignored", "https://H.Example.com/a", "https://h.example.com/b", true},
		{"scheme differs", "http://h.example.com/a", "https://h.example.com/a", false},
		{"explicit 443 versus explicit 80", "https://h.example.com:443/a", "http://h.example.com:80/a", false},
		{"non-default port differs", "https://h.example.com/a", "https://h.example.com:8443/a", false},
		{"host differs", "https://h.example.com/a", "https://other.example.com/a", false},
	}
	for _, tc := range cases {
		a, errA := url.Parse(tc.a)
		b, errB := url.Parse(tc.b)
		if errA != nil || errB != nil {
			t.Fatalf("%s: bad fixture URL: %v %v", tc.name, errA, errB)
		}
		if got := sameOrigin(a, b); got != tc.want {
			t.Errorf("%s: sameOrigin(%s, %s) = %v, want %v", tc.name, tc.a, tc.b, got, tc.want)
		}
	}
	if sameOrigin(nil, nil) {
		t.Error("expected a missing URL never to count as the same origin")
	}
}

// followRedirectMethod answers the first request with the given redirect status
// and a Location, and returns the method the followed request was sent with.
func followRedirectMethod(t *testing.T, status int, method string) string {
	t.Helper()
	var followed string
	mux := http.NewServeMux()
	mux.HandleFunc("/start", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Location", "/landed")
		w.WriteHeader(status)
	})
	mux.HandleFunc("/landed", func(w http.ResponseWriter, r *http.Request) {
		followed = r.Method
		w.WriteHeader(200)
	})
	server := httptest.NewServer(mux)
	defer server.Close()

	transport, err := NewTransportOptionsBuilder().FollowRedirects(true).Build()
	if err != nil {
		t.Fatal(err)
	}
	client := NewDefaultApiClient(transport)
	if _, err := client.SendRequest(method, server.URL+"/start", map[string]string{}, []byte("payload")); err != nil {
		t.Fatalf("%d %s: unexpected error: %v", status, method, err)
	}
	return followed
}

// A redirect rewrites the method only as RFC 9110 section 15.4 allows: a 301 or
// 302 turns only a POST into a GET, a 303 turns every method but HEAD into a GET,
// and a 307 or 308 keeps the method.
func TestBhvRedirects029_DefaultApiClientUnit_RedirectRewritesTheMethodOnlyAsRFC9110Allows(t *testing.T) {
	t.Parallel()
	for _, tc := range []struct {
		status int
		method string
		want   string
	}{
		{301, "POST", "GET"}, {301, "PUT", "PUT"}, {301, "PATCH", "PATCH"}, {301, "DELETE", "DELETE"},
		{302, "POST", "GET"}, {302, "PUT", "PUT"}, {302, "DELETE", "DELETE"},
		{303, "POST", "GET"}, {303, "PUT", "GET"}, {303, "DELETE", "GET"}, {303, "HEAD", "HEAD"},
		{307, "POST", "POST"}, {307, "PUT", "PUT"}, {308, "PATCH", "PATCH"}, {308, "DELETE", "DELETE"},
	} {
		if got := followRedirectMethod(t, tc.status, tc.method); got != tc.want {
			t.Errorf("%d %s: expected the follow-up as %s, got %s", tc.status, tc.method, tc.want, got)
		}
	}
}

// A 303 turns every method except HEAD into a GET.
func TestBhvRedirects036_DefaultApiClientUnit_A303TurnsEveryMethodExceptHeadIntoGet(t *testing.T) {
	t.Parallel()
	for method, want := range map[string]string{"POST": "GET", "PUT": "GET", "PATCH": "GET", "DELETE": "GET", "HEAD": "HEAD"} {
		if got := followRedirectMethod(t, 303, method); got != want {
			t.Errorf("303 %s: expected the follow-up as %s, got %s", method, want, got)
		}
	}
}

